const out=[];
for (const it of $input.all()) {
  const w=$('Worlds').all()[out.length]?.json || {};
  let q=[]; try { q = Array.isArray(it.json) ? it.json : JSON.parse(it.json.data || '[]'); } catch(e) {}
  const by=s=>q.filter(t=>t.status===s).map(t=>t.id+' '+String(t.title).slice(0,70));
  const brief=`World: ${w.name}\nTodo: ${by('todo').join('; ')||'none'}\nIn review: ${by('review').join('; ')||'none'}\nRejected: ${by('rejected').join('; ')||'none'}`;
  out.push({json:{world:w.name, body:{model:'openai/gpt-oss-20b',temperature:0.3,max_tokens:400,messages:[
    {role:'system',content:'You are the morning council of one Kalpa Labs world. Soft launch is Sun 13 Dec 2026, Pilot Day Mon 16 Nov. Using ONLY the queue below, give the 2 most important next actions in plain short English, each under 20 words, and say who does it: agents, Claude (code) or Akhil. No invented facts.'},
    {role:'user',content:brief}]}}});
}
return out;

